import { describe, expect, test } from 'vitest';
import type { Unzipped } from 'fflate';

import { normalizeAndFilterZipFiles } from '@/lib/utils/security';
import { generateTestId } from '@/lib/utils/testId';

// Helpers
const enc = (s: string): Uint8Array => new TextEncoder().encode(s);

describe('normalizeAndFilterZipFiles', () => {
  describe('unix-style paths', () => {
    test('strips the prefix and keeps expected files', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'),
        [`${testId}/metrics.json`]: enc('{}'),
        [`${testId}/screenshot.png`]: enc('png'),
        [`${testId}/pageload.har`]: enc('har'),
        [`${testId}/resources.json`]: enc('{}'),
        [`${testId}/console.json`]: enc('{}'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(Object.keys(result).sort()).toEqual([
        'config.json',
        'console.json',
        'metrics.json',
        'pageload.har',
        'resources.json',
        'screenshot.png',
      ]);
    });

    test('keeps webm video files at root level', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'),
        [`${testId}/recording.webm`]: enc('webm'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(Object.keys(result)).toContain('recording.webm');
    });

    test('keeps filmstrip jpg files', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'),
        [`${testId}/filmstrip/frame001.jpg`]: enc('jpg'),
        [`${testId}/filmstrip/frame002.jpg`]: enc('jpg'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(Object.keys(result)).toContain('filmstrip/frame001.jpg');
      expect(Object.keys(result)).toContain('filmstrip/frame002.jpg');
    });

    test('silently drops unexpected files', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'),
        [`${testId}/index.html`]: enc('<html>'),
        [`${testId}/secret.txt`]: enc('secret'),
        [`${testId}/malware.exe`]: enc('exe'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(Object.keys(result)).toEqual(['config.json']);
      expect(Object.keys(result)).not.toContain('index.html');
      expect(Object.keys(result)).not.toContain('secret.txt');
      expect(Object.keys(result)).not.toContain('malware.exe');
    });

    test('excludes files that do not start with the given prefix', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const otherId = generateTestId('2024-06-01T00:00:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'),
        [`${otherId}/config.json`]: enc('{}'),
        'config.json': enc('{}'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(Object.keys(result)).toEqual(['config.json']);
    });

    test('preserves file contents after normalization', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const content = enc('{"url":"https://example.com"}');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: content,
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}/`);

      expect(result['config.json']).toBe(content);
    });

    test('works with an empty prefix (no directory nesting)', () => {
      const unzipped: Unzipped = {
        'config.json': enc('{}'),
        'metrics.json': enc('{}'),
        'index.html': enc('<html>'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, '');

      expect(Object.keys(result).sort()).toEqual([
        'config.json',
        'metrics.json',
      ]);
    });

    test('files at zip root with filmstrip subfolder and no parent testId folder', () => {
      // Mirrors the real upload.ts logic: when config.json is at the root,
      // path.dirname returns '.', so prefixToStrip is set to ''.
      const unzipped: Unzipped = {
        'config.json': enc('{}'),
        'metrics.json': enc('{}'),
        'screenshot.png': enc('png'),
        'pageload.har': enc('har'),
        'resources.json': enc('{}'),
        'console.json': enc('{}'),
        'recording.webm': enc('webm'),
        'filmstrip/frame001.jpg': enc('jpg'),
        'filmstrip/frame002.jpg': enc('jpg'),
        'index.html': enc('<html>'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, '');

      expect(Object.keys(result).sort()).toEqual([
        'config.json',
        'console.json',
        'filmstrip/frame001.jpg',
        'filmstrip/frame002.jpg',
        'metrics.json',
        'pageload.har',
        'recording.webm',
        'resources.json',
        'screenshot.png',
      ]);
      expect(Object.keys(result)).not.toContain('index.html');
    });
  });

  describe('windows-style paths', () => {
    test('strips the prefix and normalizes backslash separators', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}\\config.json`]: enc('{}'),
        [`${testId}\\metrics.json`]: enc('{}'),
        [`${testId}\\screenshot.png`]: enc('png'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}\\`);

      // path.normalize on the current (posix) platform won't convert backslashes,
      // but on Windows it would — the test asserts the function handles the prefix
      // stripping correctly regardless of separator style in the input object keys.
      const keys = Object.keys(result);
      // At least the prefix-stripped, allowlisted files survive
      expect(keys.length).toBeGreaterThan(0);
      // None of the surviving keys should still carry the testId\ prefix
      keys.forEach(k => expect(k.startsWith(`${testId}\\`)).toBe(false));
    });

    test('drops unexpected files from windows-style paths', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}\\config.json`]: enc('{}'),
        [`${testId}\\index.html`]: enc('<html>'),
        [`${testId}\\malware.exe`]: enc('exe'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}\\`);

      const keys = Object.keys(result);
      const hasIndexHtml = keys.some(k => k.includes('index.html'));
      const hasMalware = keys.some(k => k.includes('malware.exe'));
      expect(hasIndexHtml).toBe(false);
      expect(hasMalware).toBe(false);
    });

    test('filmstrip paths with backslash separators survive filtering', () => {
      // On Windows, ZIP entries may use backslashes for subdirectory separators.
      // path.normalize should convert backslashes to forward slashes so that
      // isExpectedTelescopeFile() can match the 'filmstrip/*.jpg' rule.
      // This test will FAIL on POSIX because path.normalize does not convert
      // backslashes there — exposing a real portability bug in the code.
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}\\config.json`]: enc('{}'),
        [`${testId}\\filmstrip\\frame001.jpg`]: enc('jpg'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, `${testId}\\`);

      const keys = Object.keys(result);
      const hasFilmstrip = keys.some(k => k.includes('frame001.jpg'));
      expect(hasFilmstrip).toBe(true);
    });

    test('files at zip root with filmstrip subfolder using backslash separators and no parent testId folder', () => {
      // Same scenario as the POSIX test above but with Windows-style backslash
      // separators in the ZIP entry keys and an empty prefix.
      // The filmstrip entry uses a backslash separator: 'filmstrip\frame001.jpg'.
      // On POSIX, path.normalize does NOT convert that backslash, so
      // path.dirname returns '.' instead of 'filmstrip' and the entry is dropped
      // by isExpectedTelescopeFile — exposing the same portability bug as the
      // nested-folder filmstrip test above.
      const unzipped: Unzipped = {
        'config.json': enc('{}'),
        'metrics.json': enc('{}'),
        'screenshot.png': enc('png'),
        'pageload.har': enc('har'),
        'resources.json': enc('{}'),
        'console.json': enc('{}'),
        'recording.webm': enc('webm'),
        'filmstrip\\frame001.jpg': enc('jpg'),
        'filmstrip\\frame002.jpg': enc('jpg'),
        'index.html': enc('<html>'),
      };

      const result = normalizeAndFilterZipFiles(unzipped, '');

      expect(Object.keys(result)).toContain('filmstrip/frame001.jpg');
      expect(Object.keys(result)).toContain('filmstrip/frame002.jpg');
      expect(Object.keys(result)).not.toContain('index.html');
    });

    test('excludes files whose prefix uses forward slashes when backslash prefix is given', () => {
      const testId = generateTestId('2024-01-15T10:30:00Z');
      const unzipped: Unzipped = {
        [`${testId}/config.json`]: enc('{}'), // forward-slash key
        [`${testId}\\config.json`]: enc('{}'), // backslash key
      };

      // Only the backslash-prefixed entry should match
      const result = normalizeAndFilterZipFiles(unzipped, `${testId}\\`);

      // Exactly one config.json survives
      const configEntries = Object.keys(result).filter(k =>
        k.endsWith('config.json'),
      );
      expect(configEntries).toHaveLength(1);
    });
  });
});

import { BrowserConfig } from '../src/browsers.js';
import fs from 'fs';
import { describe, expect, test } from 'vitest';
import type { BrowserName } from '../src/types.js';

const browsers = BrowserConfig.getBrowsers();

describe('Specific browser tests', () => {
  test('Initializing with an invalid browser throws an error', () => {
    const options = {
      browser: 'hotdog' as BrowserName,
      url: '../tests/sandbox/index.html',
    };
    expect(() =>
      new BrowserConfig().getBrowserConfig('hotdog' as BrowserName, options),
    ).toThrow(Error);
  });

  test('Passing Firefox preferences creates a user data dir and file', () => {
    const options = {
      browser: 'firefox' as BrowserName,
      firefoxPrefs: { 'image.avif.enabled': false },
      url: '../tests/sandbox/index.html',
    };
    const config = new BrowserConfig().getBrowserConfig('firefox', options);
    expect(config && typeof config === 'object').toBe(true);
    expect(fs.existsSync('./tmp')).toBe(true);
    expect(fs.existsSync('./tmp/user.js')).toBe(true);

    //clean up after ourselves
    fs.rmSync('./tmp', { recursive: true, force: true });
  });

  //test for default chrome flag add and remove
});

describe.each(browsers)('Basic configuration tests: %s', browser => {
  test('Initializing with a valid browser results in a config', () => {
    const options = {
      browser,
      url: '../tests/sandbox/index.html',
    };
    const config = new BrowserConfig().getBrowserConfig(browser, options);
    expect(config && typeof config === 'object').toBe(true);
  });

  test('Setting a viewport updates the config', () => {
    const options = {
      browser,
      width: 500,
      height: 700,
      url: '../tests/sandbox/index.html',
    };
    const config = new BrowserConfig().getBrowserConfig(browser, options);
    expect(config && typeof config === 'object').toBe(true);
    expect(config.viewport.width === 500).toBe(true);
    expect(config.viewport.height === 700).toBe(true);
  });

  test('Setting a viewport updates the video size', () => {
    const options = {
      browser,
      width: 500,
      height: 700,
      url: '../tests/sandbox/index.html',
    };
    const config = new BrowserConfig().getBrowserConfig(browser, options);
    expect(config && typeof config === 'object').toBe(true);
    expect(config.recordVideo.size.width === 500).toBe(true);
    expect(config.recordVideo.size.height === 700).toBe(true);
  });

  test('Setting a viewport with a string throws an error', () => {
    const options = {
      browser,
      width: 'asdf' as unknown as number,
      height: 'asdf' as unknown as number,
      url: '../tests/sandbox/index.html',
    };
    // Note: The original test expected an error, but the current implementation
    // doesn't throw. If it does throw after validation is added, update this test.
    const config = new BrowserConfig().getBrowserConfig(browser, options);
    expect(config && typeof config === 'object').toBe(true);
  });

  test('Set the User Agent the browser tells the website', () => {
    const options = {
      browser,
      userAgent:
        'Mozilla/5.0 (Windows; U; MSIE 6.0; Windows NT 5.1; SV1; .NET CLR 2.0.50727)',
      url: '../tests/sandbox/index.html',
    };
    const config = new BrowserConfig().getBrowserConfig(browser, options);
    expect(config && typeof config === 'object').toBe(true);
    expect(
      config.userAgent ===
        'Mozilla/5.0 (Windows; U; MSIE 6.0; Windows NT 5.1; SV1; .NET CLR 2.0.50727)',
    ).toBe(true);
  });

  //test for other options
});

import playwright from 'playwright';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import type { Browser, Page } from 'playwright';

import { collectAvailableJSAPIs } from '../src/baselineJsApiAvailability.js';
import { JS_API_REGISTRY } from '../src/baselineJsApiRegistry.js';
import { BrowserConfig } from '../src/browsers.js';
import type { JSAPIKind, JSAPIRegistryEntry } from '../src/types.js';

function api(
  bcdKey: string,
  kind: JSAPIKind,
  path: string,
): JSAPIRegistryEntry {
  return { bcdKey, kind, path };
}

describe('JS_API_REGISTRY', () => {
  it('contains representative API shapes from the curated prototype', () => {
    expect(JS_API_REGISTRY).toEqual(
      expect.arrayContaining([
        api('api.IntersectionObserver', 'constructor', 'IntersectionObserver'),
        api('api.fetch', 'global_function', 'fetch'),
        api('api.Navigator.sendBeacon', 'method', 'navigator.sendBeacon'),
        api(
          'api.Document.adoptedStyleSheets',
          'property',
          'Document.prototype.adoptedStyleSheets',
        ),
        api('api.Navigator.clipboard', 'property', 'navigator.clipboard'),
        api(
          'api.Document.startViewTransition',
          'method',
          'document.startViewTransition',
        ),
        api('api.AbortSignal.any_static', 'static_method', 'AbortSignal.any'),
        api('api.structuredClone', 'global_function', 'structuredClone'),
      ]),
    );
  });

  it('has one non-empty BCD key and global path per entry', () => {
    const bcdKeys = JS_API_REGISTRY.map(entry => entry.bcdKey);
    const paths = JS_API_REGISTRY.map(entry => entry.path);

    expect(JS_API_REGISTRY.length).toBeGreaterThan(0);
    expect(bcdKeys.every(Boolean)).toBe(true);
    expect(paths.every(Boolean)).toBe(true);
    expect(new Set(bcdKeys).size).toBe(bcdKeys.length);
    expect(new Set(paths).size).toBe(paths.length);
  });
});

const browsers = BrowserConfig.getBrowsers();

describe.each(browsers)('collectAvailableJSAPIs — %s', browserName => {
  const config = BrowserConfig.browserConfigs[browserName];
  let browser: Browser;

  beforeAll(async () => {
    browser = await playwright[config.engine].launch({
      headless: config.headless,
      ...('channel' in config && config.channel
        ? { channel: config.channel }
        : {}),
    });
  }, 120000);

  afterAll(async () => {
    await browser.close();
  });

  async function withPage<T>(fn: (page: Page) => Promise<T>): Promise<T> {
    const page = await browser.newPage();
    try {
      await page.setContent('<main>availability test</main>');
      return await fn(page);
    } finally {
      await page.close();
    }
  }

  it('reports available APIs by BCD key and skips unavailable APIs', async () => {
    const registry: readonly JSAPIRegistryEntry[] = [
      api('test.property', 'property', 'document.body'),
      api('test.constructor', 'constructor', 'URL'),
      api('test.global_function', 'global_function', 'structuredClone'),
      api('test.method', 'method', 'Array.prototype.flat'),
      api('test.static_method', 'static_method', 'Promise.allSettled'),
      api('test.missing', 'property', '__telescopeMissingApi.value'),
      api('test.not_callable', 'method', 'document.body'),
    ];

    const available = await withPage(page =>
      collectAvailableJSAPIs(page, registry),
    );

    expect(available).toEqual([
      'test.constructor',
      'test.global_function',
      'test.method',
      'test.property',
      'test.static_method',
    ]);
  });

  it('isolates throwing lookups and does not invoke the final property getter', async () => {
    const registry: readonly JSAPIRegistryEntry[] = [
      api(
        'test.throwing_parent',
        'property',
        '__availabilityFixture.throwingParent.value',
      ),
      api(
        'test.throwing_property',
        'property',
        '__availabilityFixture.throwingProperty',
      ),
      api(
        'test.still_available',
        'property',
        '__availabilityFixture.stillAvailable',
      ),
    ];

    const available = await withPage(async page => {
      await page.evaluate(() => {
        const fixture = { stillAvailable: true };
        Object.defineProperties(fixture, {
          throwingParent: {
            get() {
              throw new Error('parent getter must be isolated');
            },
          },
          throwingProperty: {
            get() {
              throw new Error('final getter must not run');
            },
          },
        });
        Object.defineProperty(globalThis, '__availabilityFixture', {
          configurable: true,
          value: fixture,
        });
      });

      return collectAvailableJSAPIs(page, registry);
    });

    expect(available).toEqual([
      'test.still_available',
      'test.throwing_property',
    ]);
  });

  it('deduplicates and sorts results without replacing browser APIs', async () => {
    const registry: readonly JSAPIRegistryEntry[] = [
      api('test.url', 'constructor', 'URL'),
      api('test.array', 'method', 'Array.prototype.flat'),
      api('test.url', 'constructor', 'URL'),
    ];

    const result = await withPage(async page => {
      await page.evaluate(() => {
        Object.defineProperties(globalThis, {
          __originalArrayFlat: { value: Array.prototype.flat },
          __originalURL: { value: URL },
        });
      });
      const available = await collectAvailableJSAPIs(page, registry);
      const identitiesUnchanged = await page.evaluate(() => {
        const fixture = globalThis as typeof globalThis & {
          __originalArrayFlat: typeof Array.prototype.flat;
          __originalURL: typeof URL;
        };
        return (
          Array.prototype.flat === fixture.__originalArrayFlat &&
          URL === fixture.__originalURL
        );
      });
      return { available, identitiesUnchanged };
    });

    expect(result).toEqual({
      available: ['test.array', 'test.url'],
      identitiesUnchanged: true,
    });
  });

  it('detects representative entries from the production registry', async () => {
    const available = await withPage(page => collectAvailableJSAPIs(page));

    expect(available).toEqual(
      expect.arrayContaining([
        'api.URL',
        'api.fetch',
        'javascript.builtins.Array.flat',
      ]),
    );
  });
});

