import path from 'node:path';
import type { Unzipped } from 'fflate';

// Expected Telescope output files
// Could be expanded/formalized into actual manifest
export const EXPECTED_TELESCOPE_FILES = new Set([
  'config.json',
  'metrics.json',
  'resources.json',
  'console.json',
  'pageload.har',
  'screenshot.png',
]);

// Validate testId format: YYYY_MM_DD_HH_MM_SS_UUID
export function isValidTestId(testId: string): boolean {
  const testIdPattern =
    /^\d{4}_\d{2}_\d{2}_\d{2}_\d{2}_\d{2}_[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
  return testIdPattern.test(testId);
}

// ZIP files can be created on Windows (with backslashes) or Unix (with forward slashes)
// Inside telescope-web, normalize ALL zip filepaths to POSIX format (forward slashes) for cross-platform ZIP handling
export function toPosixPath(filepath: string): string {
  return filepath.split('\\').join('/');
}

// Check if filename matches expected Telescope output patterns
// Expected: config.json, metrics.json, screenshot.png, pageload.har, resources.json, console.json, *.webm, filmstrip/*.jpg
// Assumes filename is already normalized to POSIX format (forward slashes)
export function isExpectedTelescopeFile(filename: string): boolean {
  const lower = filename.toLowerCase();
  if (EXPECTED_TELESCOPE_FILES.has(lower)) {
    return true;
  }
  const dir = path.posix.dirname(lower);
  if (dir === '.' && lower.endsWith('.webm')) {
    return true;
  }
  if (dir === 'filmstrip' && lower.endsWith('.jpg')) {
    return true;
  }
  return false;
}

// Normalize ZIP file paths by stripping prefix, then filter to only valid, secure Telescope output files
export function normalizeAndFilterZipFiles(
  unzipped: Unzipped,
  prefixToStrip: string,
): Unzipped {
  return Object.entries(unzipped)
    .filter(([originalFilePath]) => originalFilePath.startsWith(prefixToStrip))
    .map(
      ([originalFilePath, contents]) =>
        [
          toPosixPath(originalFilePath.slice(prefixToStrip.length)),
          contents,
        ] as const,
    )
    .filter(([normalizedFilePath]) =>
      isExpectedTelescopeFile(normalizedFilePath),
    )
    .reduce((acc, [normalizedFilePath, contents]) => {
      acc[normalizedFilePath] = contents;
      return acc;
    }, {} as Unzipped);
}

import type { Page } from 'playwright';

import { JS_API_REGISTRY } from './baselineJsApiRegistry.js';
import type { JSAPIRegistryEntry } from './types.js';

/**
 * Collects curated JavaScript and Web APIs available in an already-loaded page.
 * The lookup is read-only and isolates individual APIs whose property access
 * throws so they cannot prevent the rest of the registry from being checked.
 *
 * @param page - A Playwright page in the browser being inventoried.
 * @param registry - Registry to inspect; defaults to {@link JS_API_REGISTRY}.
 * @returns Sorted, deduplicated BCD keys for APIs available in the page.
 */
export async function collectAvailableJSAPIs(
  page: Page,
  registry: readonly JSAPIRegistryEntry[] = JS_API_REGISTRY,
): Promise<string[]> {
  return page.evaluate(entries => {
    const available = new Set<string>();

    for (const entry of entries) {
      try {
        const parts = entry.path.split('.');
        const property = parts.pop();
        let parent: unknown = globalThis;

        if (!property) continue;

        for (const part of parts) {
          if (
            parent === null ||
            (typeof parent !== 'object' && typeof parent !== 'function') ||
            !(part in parent)
          ) {
            parent = undefined;
            break;
          }
          parent = (parent as Record<string, unknown>)[part];
        }

        if (
          parent === null ||
          (typeof parent !== 'object' && typeof parent !== 'function') ||
          !(property in parent)
        ) {
          continue;
        }

        if (
          entry.kind === 'property' ||
          typeof (parent as Record<string, unknown>)[property] === 'function'
        ) {
          available.add(entry.bcdKey);
        }
      } catch {
        // Host objects may throw during lookup; availability is best-effort per API.
      }
    }

    return [...available].sort();
  }, registry);
}

import fs from 'fs';
import type {
  BrowserName,
  BrowserConfigOptions,
  BrowserConfigEntry,
  LaunchOptions,
} from './types.js';
import { DEFAULT_BROWSER_HEIGHT, DEFAULT_BROWSER_WIDTH } from './defaultOptions.js';

const TRUTHY_VALUES = new Set(['true', '1', 'yes', 'on']);
const FALSY_VALUES = new Set(['false', '0', 'no', 'off']);

/**
 * Parse an environment variable string as a boolean.
 * Truthy values: 'true', '1', 'yes', 'on' (case-insensitive).
 * Falsy values: 'false', '0', 'no', 'off' (case-insensitive).
 * Unrecognised values fall back to `defaultValue`.
 */
function parseEnvBool(
  value: string | undefined,
  defaultValue: boolean,
): boolean {
  if (value === undefined) return defaultValue;
  const lower = value.toLowerCase();
  if (TRUTHY_VALUES.has(lower)) return true;
  if (FALSY_VALUES.has(lower)) return false;
  return defaultValue;
}

// should browsers be headless? defaults to false unless running in CI
// but can be overridden by explicitly setting HEADLESS to any truthy/falsy value
const CI = parseEnvBool(process.env.CI, false);

const headless: boolean = parseEnvBool(process.env.HEADLESS, CI);

type BrowserConfigs = Record<BrowserName, BrowserConfigEntry>;

// Check if running as root (uid 0) - requires --no-sandbox for Chrome
const isRoot = process.getuid?.() === 0;

class BrowserConfig {
  defaultChromiumArgs: string[] = [
    '--allow-running-insecure-content',
    '--disable-background-networking',
    '--disable-background-timer-throttling',
    '--disable-backgrounding-occluded-windows',
    '--disable-breakpad',
    '--disable-client-side-phishing-detection',
    '--disable-component-update',
    '--disable-default-apps',
    '--disable-domain-reliability',
    '--disable-fetching-hints-at-navigation-start',
    '--disable-hang-monitor',
    '--disable-ipc-flooding-protection',
    '--disable-prompt-on-repost',
    '--disable-renderer-backgrounding',
    '--disable-sync',
    '--metrics-recording-only',
    '--mute-audio',
    '--new-window',
    '--no-default-browser-check',
    '--no-first-run',
    '--password-store=basic',
    '--use-mock-keychain',
    '--window-position="0,0"',
    '--window-size="1366,768"',
    '--remote-debugging-port=0',
    // Required when running as root (Chrome won't start with sandbox enabled as root)
    ...(isRoot ? ['--no-sandbox', '--disable-setuid-sandbox'] : []),
  ];

  defaultIgnoreArgs: string[] = [
    //this one is causing padding on the video oddly...
    //since the reported issue is the opposite: https://bugs.chromium.org/p/chromium/issues/detail?id=1277272
    // '--enable-automation',
    // Ignore Playwright's default --no-sandbox when not root (force sandboxing for security)
    // When running as root, we explicitly add --no-sandbox via defaultChromiumArgs
    ...(isRoot ? [] : ['--no-sandbox']),
  ];

  defaultBrowserOptions: Pick<
    BrowserConfigOptions,
    'headless' | 'viewport' | 'recordHar' | 'recordVideo'
  > = {
    headless,
    viewport: { width: 1366, height: 768 },
    recordHar: {
      path: './results/example.har',
    },
    recordVideo: {
      dir: './recordings',
      size: { width: 1366, height: 768 },
    },
  };

  static browserConfigs: BrowserConfigs = {
    chrome: {
      engine: 'chromium',
      channel: 'chrome',
      headless,
      flags: true,
      args: [],
    },
    chromium: { // AKA Google Chrome for Testing from Playwright CI image
      engine: 'chromium',
      channel: 'chromium',
      headless,
      flags: true,
      args: [],
    },
    'chrome-beta': {
      engine: 'chromium',
      channel: 'chrome-beta',
      headless,
      flags: true,
      args: [],
    },
    //canary seems to be failing 3/14
    canary: {
      engine: 'chromium',
      channel: 'chrome-canary',
      headless,
      flags: true,
      args: [],
    },
    firefox: {
      engine: 'firefox',
      headless,
      firefoxUserPrefs: {},
      mozLog: false,
    },
    safari: {
      engine: 'webkit',
      headless,
    },
    edge: {
      engine: 'chromium',
      channel: 'msedge',
      headless,
      flags: true,
      args: [],
    },
  };

  browser: BrowserName | undefined;

  constructor(browser?: BrowserName) {
    this.browser = browser;
  }

  static getBrowsers(): BrowserName[] {
    const configuredBrowsers = Object.keys(
      BrowserConfig.browserConfigs,
    ) as BrowserName[];

    // only run firefox in CI (for now)
    if (CI) {
      return ['firefox'];
    }

    if (process.env.BROWSERS) {
      const requestedBrowsers = process.env.BROWSERS.split(/[,\s]+/)
        .map(browser => browser.trim().toLowerCase())
        .filter(browser => browser.length > 0);

      const envBrowsers = requestedBrowsers.filter(browser =>
        configuredBrowsers.includes(browser as BrowserName),
      ) as BrowserName[];

      const invalidBrowsers = requestedBrowsers.filter(
        browser => !configuredBrowsers.includes(browser as BrowserName),
      );

      if (invalidBrowsers.length > 0) {
        console.warn(
          `Ignoring unsupported browser name(s) from BROWSERS environment variable: ${invalidBrowsers.join(
            ', ',
          )}`,
        );
      }

      if (envBrowsers.length === 0) {
        console.warn(
          'No valid browsers specified in BROWSERS environment variable; returning an empty browser list.',
        );
      }

      return envBrowsers;
    }

    return configuredBrowsers;
  }

  addFirefoxPrefs(prefs: Record<string, string | number | boolean>): void {
    const userPrefLines: string[] = [];
    for (const [key, value] of Object.entries(prefs)) {
      let prefline: string;
      if (typeof value == 'boolean') {
        prefline = `user_pref("${key}", ${value});\n`;
      } else {
        prefline = `user_pref("${key}", "${value}");\n`;
      }
      userPrefLines.push(prefline);
    }
    userPrefLines.forEach(s => fs.appendFileSync('./tmp/user.js', s));
  }

  createUserDataDir(browserConfig: BrowserConfigEntry): void {
    //let's make sure there's a user directory
    const userDataDir = './tmp';
    if (!fs.existsSync(userDataDir)) {
      fs.mkdirSync(userDataDir);
    }
    if (browserConfig.engine == 'firefox') {
      //let's copy over our starter user.js
      // eventually, it'd be nice to avoid this but playwright doesn't
      // let you set firefox user pref on an persisted context
      fs.copyFile('./support/firefox/user.js', './tmp/user.js', err => {
        if (err) {
          console.error('Error Creating User Data Directory:', err);
        }
      });
    }
  }

  getBrowserConfig(
    browser: BrowserName,
    options: LaunchOptions,
  ): BrowserConfigOptions {
    //check for browser and see if it has value
    if (
      !Object.prototype.hasOwnProperty.call(
        BrowserConfig.browserConfigs,
        browser,
      )
    ) {
      throw new Error('Invalid browser name');
    }

    const baseConfig = BrowserConfig.browserConfigs[browser];
    const browserConfig: BrowserConfigOptions = {
      ...baseConfig,
      ...this.defaultBrowserOptions,
    };

    // Handle Chromium-specific args
    if ('args' in baseConfig && baseConfig.args) {
      browserConfig.args = [...baseConfig.args, ...this.defaultChromiumArgs];
      if (options.args) {
        browserConfig.args = [...browserConfig.args, ...options.args];
      }
      browserConfig.ignoreDefaultArgs = this.defaultIgnoreArgs;
    }

    // Handle Firefox preferences
    if (
      'firefoxUserPrefs' in baseConfig &&
      baseConfig.firefoxUserPrefs &&
      options.firefoxPrefs
    ) {
      this.createUserDataDir(baseConfig);
      this.addFirefoxPrefs(options.firefoxPrefs);
      browserConfig.firefoxUserPrefs = options.firefoxPrefs || {};
    }

    // Handle Firefox mozLog
    if ('mozLog' in baseConfig && baseConfig.mozLog) {
      //quick test for firefox
      browserConfig.env = {
        MOZ_LOG_FILE: 'moz.log',
        MOZ_LOG:
          'timestamp,nsHttp:{0:d},nsSocketTransport:{0:d},nsHostResolver:{0:d},pipnss:5',
      };
    }

    // resolve viewport dimensions: explicit user value > device value > fallback default
    const resolvedWidth =
      options.width ??
      options.device?.viewport.width
      ?? DEFAULT_BROWSER_WIDTH;
    const resolvedHeight =
      options.height ??
      options.device?.viewport.height ??
      DEFAULT_BROWSER_HEIGHT;

    browserConfig.viewport.width = resolvedWidth;
    browserConfig.viewport.height = resolvedHeight;
    browserConfig.recordVideo.size.width = resolvedWidth;
    browserConfig.recordVideo.size.height = resolvedHeight;

    // collect device info and insert device emulation settings into browser config
    if (options.device) {
      browserConfig.userAgent = options.device.userAgent;
      browserConfig.deviceScaleFactor = options.device.deviceScaleFactor;
      browserConfig.isMobile = options.device.isMobile;
      browserConfig.hasTouch = options.device.hasTouch;
    }

    if (options.userAgent) {
      browserConfig.userAgent = options.userAgent;
    }

    return browserConfig;
  }
}

export { BrowserConfig };
